// ============================================================
// FILE: backend/services/businessDb.service.js
// PURPOSE: Gateway to the business (ERP) database.
//   - Introspects tables & schemas for AI context
//   - Executes read-only SQL queries generated by AI
//   - Provides schema info so AI can write correct SQL
// ============================================================

const bizSupabase = require('../config/businessDb');

// ── Cache schema after first fetch ──
let schemaCache = null;
let lastFetched = 0;
const SCHEMA_CACHE_TTL = 10 * 60 * 1000; // 10 min

/**
 * Load foreign key relationships from information_schema
 * Returns map: { 'tableName.columnName': { ref_table, ref_column } }
 */
const loadForeignKeyMap = async () => {
  const fkSQL = `
    SELECT
      kcu.table_name,
      kcu.column_name,
      ccu.table_name AS foreign_table_name,
      ccu.column_name AS foreign_column_name
    FROM information_schema.table_constraints AS tc
    JOIN information_schema.key_column_usage AS kcu
      ON tc.constraint_name = kcu.constraint_name
      AND tc.table_schema = kcu.table_schema
    JOIN information_schema.constraint_column_usage AS ccu
      ON ccu.constraint_name = tc.constraint_name
      AND ccu.table_schema = tc.table_schema
    WHERE tc.constraint_type = 'FOREIGN KEY'
      AND tc.table_schema = 'public'
  `;
  try {
    const rows = await executeRawSQL(fkSQL);
    if (!Array.isArray(rows)) return {};
    const map = {};
    for (const row of rows) {
      const key = `${row.table_name}.${row.column_name}`;
      map[key] = { ref_table: row.foreign_table_name, ref_column: row.foreign_column_name };
    }
    return map;
  } catch (err) {
    console.warn('[BizDB] FK introspection failed:', err.message);
    return {};
  }
};

/**
 * Execute raw SQL via RPC (the only way to query information_schema)
 * Falls back gracefully if RPC function doesn't exist yet
 */
const executeRawSQL = async (sql) => {
  // Security: only allow SELECT/WITH queries
  const trimmed = sql.trim().toUpperCase();
  if (!trimmed.startsWith('SELECT') && !trimmed.startsWith('WITH')) {
    throw new Error('Only SELECT queries are allowed');
  }

  // Block dangerous keywords
  const dangerous = /\b(INSERT|UPDATE|DELETE|DROP|ALTER|CREATE|TRUNCATE|EXEC|EXECUTE|CALL|MERGE|REPLACE)\b/i;
  if (dangerous.test(sql)) {
    throw new Error('Only read-only queries are allowed');
  }

  // Strip trailing semicolons — Supabase RPC doesn't accept them
  const cleanSql = sql.replace(/;\s*$/, '').trim();

  console.log(`[BizDB] Executing SQL (${cleanSql.split('\n')[0].slice(0, 80)}...)`);

  const { data, error } = await bizSupabase.rpc('execute_biz_query', {
    query_text: cleanSql,
  });

  if (error) {
    console.error(`[BizDB] RPC error:`, error);
    // Check if the RPC function itself is missing
    if (error.message?.includes('function') && (error.message?.includes('not found') || error.message?.includes('exists'))) {
      throw new Error('execute_biz_query RPC not found. Run database/business_supabase_functions.sql in your business Supabase SQL editor first.');
    }
    throw new Error(`DB query failed: ${error.message}`);
  }

  // execute_biz_query returns JSONB. It could be a JSON array or a single JSON object.
  if (data === null || data === undefined) return [];
  
  // If it's already an array, return as-is
  if (Array.isArray(data)) return data;
  
  // If it's a JSON object with numeric keys, convert to array
  if (typeof data === 'object') {
    const keys = Object.keys(data);
    if (keys.every(k => !isNaN(parseInt(k)))) {
      return Object.values(data);
    }
    return [data];
  }
  
  return data;
};

/**
 * Introspect all user-defined tables in the business DB
 * Returns [{ table_name, table_type, columns: [{ column_name, data_type, is_nullable, max_length }] }]
 */
const getTableSchemas = async (forceRefresh = false) => {
  const now = Date.now();
  if (!forceRefresh && schemaCache && (now - lastFetched) < SCHEMA_CACHE_TTL) {
    return schemaCache;
  }

  try {
    // Try the dedicated RPC function first
    const { data, error } = await bizSupabase.rpc('get_business_tables');
    
    if (!error && data) {
      // Parse JSONB result — could be array or object
      let tables = data;
      if (typeof tables === 'string') tables = JSON.parse(tables);
      if (!Array.isArray(tables) && typeof tables === 'object') {
        tables = Object.values(tables);
      }
      
      schemaCache = Array.isArray(tables) ? tables : [];

      // Annotate columns with FK references
      const fkMap = await loadForeignKeyMap();
      for (const t of schemaCache) {
        if (Array.isArray(t.columns)) {
          for (const c of t.columns) {
            const fk = fkMap[`${t.table_name}.${c.column_name}`];
            if (fk) c.foreign_key = fk;
          }
        }
      }

      lastFetched = now;
      return schemaCache;
    }
  } catch (e) {
    console.warn('[BizDB] get_business_tables RPC failed:', e.message);
  }

  // Fallback: use execute_biz_query with raw SQL
  try {
    const tablesSQL = `
      SELECT table_name, table_type 
      FROM information_schema.tables 
      WHERE table_schema = 'public' 
        AND table_type IN ('BASE TABLE', 'VIEW')
        AND table_name NOT LIKE '\\_%'
      ORDER BY table_name
    `;
    const tables = await executeRawSQL(tablesSQL);
    if (!Array.isArray(tables)) {
      schemaCache = [];
      lastFetched = now;
      return [];
    }

    const schemas = [];
    for (const table of tables) {
      const colsSQL = `
        SELECT column_name, data_type, is_nullable, character_maximum_length
        FROM information_schema.columns
        WHERE table_schema = 'public'
          AND table_name = '${table.table_name?.replace(/'/g, "''")}'
        ORDER BY ordinal_position
      `;
      try {
        const columns = await executeRawSQL(colsSQL);
        schemas.push({
          table_name: table.table_name,
          table_type: table.table_type,
          columns: Array.isArray(columns) ? columns.map(c => ({
            column_name: c.column_name,
            data_type: c.data_type,
            is_nullable: c.is_nullable,
            max_length: c.character_maximum_length,
          })) : [],
        });
      } catch {
        // Skip tables that fail
      }
    }

    // Annotate columns with FK references
    const fkMap = await loadForeignKeyMap();
    for (const t of schemas) {
      if (Array.isArray(t.columns)) {
        for (const c of t.columns) {
          const fk = fkMap[`${t.table_name}.${c.column_name}`];
          if (fk) c.foreign_key = fk;
        }
      }
    }

    schemaCache = schemas;
    lastFetched = now;
    return schemas;
  } catch (err) {
    console.error('[BizDB] Schema introspection failed:', err.message);
    schemaCache = [];
    lastFetched = now;
    return [];
  }
};

