/**
 * Build a human-readable schema description for the AI system prompt
 */
const buildSchemaContext = async () => {
  const schemas = await getTableSchemas();
  if (!schemas || schemas.length === 0) {
    return '';
  }

  // Table guide: helps AI understand what each table is for
  const guideLines = schemas
    .filter(t => TABLE_DESCRIPTIONS[t.table_name])
    .map(t => `  - ${t.table_name}: ${TABLE_DESCRIPTIONS[t.table_name]}`);

  const guideBlock = guideLines.length > 0
    ? `\n\n[TABLE GUIDE — what each table contains]\n${guideLines.join('\n')}\n[END GUIDE]`
    : '';

  const lines = schemas.map(table => {
    const cols = (table.columns || [])
      .map(c => {
        let line = `  - ${c.column_name} (${c.data_type}${c.is_nullable === 'NO' ? ', NOT NULL' : ''}${c.max_length ? `, max ${c.max_length}` : ''}`;
        if (c.foreign_key) {
          line += `) → REFERENCES ${c.foreign_key.ref_table}(${c.foreign_key.ref_column})`;
        } else {
          line += ')';
        }
        return line;
      })
      .join('\n');
    return `TABLE: ${table.table_name}\n${cols}`;
  });

  return `[BUSINESS DATABASE SCHEMA]\n${lines.join('\n\n')}\n[END SCHEMA]${guideBlock}\n\n` +
    `You have read-only access to this database. To query it, respond with:\n` +
    `[QUERY_DB]\n<SQL_QUERY>\n[/QUERY_DB]\n\n` +
    `Rules:\n` +
    `- Only SELECT queries allowed (read-only)\n` +
    `- Use table names exactly as shown above\n` +
    `- Use column names exactly as shown above\n` +
    `- Limit results with LIMIT when appropriate\n` +
    `- Do NOT use transactions, DDL, DML, or EXPLAIN\n` +
    `- Do NOT use semicolons (;) at the end of SQL queries\n` +
    `- For date queries, use ISO format (YYYY-MM-DD)\n` +
    `- Use the TABLE GUIDE above to pick the RIGHT table for the user's question`;
};

/**
 * Build a minimal schema context — TABLE GUIDE only, no full column listing.
 * AI uses GET_SCHEMA tool to fetch columns on-demand for only the tables it needs.
 */
const buildMinimalSchemaContext = async () => {
  const schemas = await getTableSchemas();
  if (!schemas || schemas.length === 0) {
    return '';
  }

  const guideLines = schemas
    .filter(t => TABLE_DESCRIPTIONS[t.table_name])
    .map(t => `  - ${t.table_name}: ${TABLE_DESCRIPTIONS[t.table_name]}`);

  const guideBlock = guideLines.length > 0
    ? `\n\n[TABLE GUIDE — what each table contains]\n${guideLines.join('\n')}\n[END GUIDE]`
    : '';

  // Build relationships section from foreign keys
  const relLines = [];
  for (const table of schemas) {
    if (!Array.isArray(table.columns)) continue;
    for (const col of table.columns) {
      if (col.foreign_key) {
        relLines.push(`  - ${table.table_name}.${col.column_name} \u2192 ${col.foreign_key.ref_table}(${col.foreign_key.ref_column})`);
      }
    }
  }

  const relBlock = relLines.length > 0
    ? `\n\n[TABLE RELATIONSHIPS — foreign keys for JOIN queries]\n${relLines.join('\n')}\n[END RELATIONSHIPS]`
    : '';

  return `[BUSINESS DATABASE — TABLES OVERVIEW]${guideBlock}${relBlock}\n\n` +
    `You have read-only access to this database. To query it:\n` +
    `1. First get column schema: [GET_SCHEMA:table1, table2, ...]\n` +
    `2. Then query: [QUERY_DB]\n   <SQL_QUERY>\n   [/QUERY_DB]\n\n` +
    `Rules:\n` +
    `- When user mentions a business entity (e.g., Purchase Order, Vendor, Sales Order), call GET_SCHEMA with ONLY its directly related tables (e.g., [GET_SCHEMA:purchase_orders, companies, vendors]) — do NOT request all tables at once; use TABLE GUIDE + RELATIONSHIPS to identify relevant tables\n` +
    `- Only SELECT queries allowed (read-only)\n` +
    `- Use table names exactly as shown in TABLE GUIDE\n` +
    `- Use column names exactly as returned by GET_SCHEMA\n` +
    `- Limit results with LIMIT when appropriate\n` +
    `- Do NOT use transactions, DDL, DML, or EXPLAIN\n` +
    `- Do NOT use semicolons (;) at the end of SQL queries\n` +
    `- For date queries, use ISO format (YYYY-MM-DD)\n` +
    `- Use the TABLE GUIDE above to pick the RIGHT table for the user's question`;
};

/**
 * Get column schema for one or more specific tables
 * @param {string|string[]} tableNames - Table name or array of table names
 * @returns {string} Formatted schema text for the requested tables
 */
const getTableSchema = async (tableNames) => {
  const schemas = await getTableSchemas();
  const names = Array.isArray(tableNames) ? tableNames : [tableNames];

  const filtered = schemas.filter(t => names.includes(t.table_name));
  if (filtered.length === 0) {
    return `[GET_SCHEMA RESULT]\nNo tables found matching: ${names.join(', ')}\n[END RESULT]`;
  }

  const lines = filtered.map(table => {
    const cols = (table.columns || [])
      .map(c => {
        let line = `  - ${c.column_name} (${c.data_type}${c.is_nullable === 'NO' ? ', NOT NULL' : ''}${c.max_length ? `, max ${c.max_length}` : ''}`;
        if (c.foreign_key) {
          line += `) → REFERENCES ${c.foreign_key.ref_table}(${c.foreign_key.ref_column})`;
        } else {
          line += ')';
        }
        return line;
      })
      .join('\n');
    return `TABLE: ${table.table_name}\n${cols}`;
  });

  return `[SCHEMA FOR: ${names.join(', ')}]\n${lines.join('\n\n')}\n[END SCHEMA]`;
};

/**
 * Execute a read-only SQL query against the business DB
 * @param {string} sql - SELECT query to execute
 * @returns {Array} rows
 */
const executeQuery = async (sql) => {
  return await executeRawSQL(sql);
};

/**
 * Execute a query with fallback
 */
const queryBusinessDB = async (sql) => {
  try {
    return await executeQuery(sql);
  } catch (err) {
    console.error('[BizDB] Query error:', err.message);
    throw err;
  }
};

/**
 * Get row count estimate for a table
 */
const getTableRowCount = async (tableName) => {
  try {
    const result = await executeRawSQL(
      `SELECT COUNT(*) as count FROM "${tableName.replace(/"/g, '""')}"`
    );
    if (Array.isArray(result) && result.length > 0) {
      return parseInt(result[0].count, 10) || 0;
    }
    // Handle case where result is a single object
    if (result && result.count !== undefined) {
      return parseInt(result.count, 10) || 0;
    }
    return 0;
  } catch {
    return null;
  }
};

/**
 * Check if business DB is connected and has execute_biz_query available
 */
const isConnected = async () => {
  try {
    await executeRawSQL('SELECT 1 as ok');
    return true;
  } catch {
    return false;
  }
};

// ── Lazy singleton: initialised once, shared across consumers ──
let _bizDbConnected = null;
let _bizDbSchemaText = '';
let _bizDbMinimalSchemaText = '';
let _initPromise = null;

/**
 * Initialise the business DB connection state (idempotent — safe to call multiple times)
 * @returns {{ connected: boolean, schemaText: string, minimalSchemaText: string }}
 */
const initBusinessDB = async () => {
  if (_bizDbConnected !== null) {
    return { connected: _bizDbConnected, schemaText: _bizDbSchemaText, minimalSchemaText: _bizDbMinimalSchemaText };
  }
  if (_initPromise) {
    return _initPromise;
  }
  _initPromise = (async () => {
    try {
      _bizDbConnected = await isConnected();
      if (_bizDbConnected) {
        _bizDbSchemaText = await buildSchemaContext();
        _bizDbMinimalSchemaText = await buildMinimalSchemaContext();
        console.log('[BizDB] ✅ Business database connected');
      } else {
        console.log('[BizDB] ⚠️ Business database not configured');
      }
    } catch (err) {
      _bizDbConnected = false;
      console.warn('[BizDB] ❌ Failed to connect:', err.message);
    }
    return { connected: _bizDbConnected, schemaText: _bizDbSchemaText, minimalSchemaText: _bizDbMinimalSchemaText };
  })();
  return _initPromise;
};

module.exports = {
  getTableSchemas,
  buildSchemaContext,
  buildMinimalSchemaContext,
  getTableSchema,
  queryBusinessDB,
  executeQuery,
  executeRawSQL,
  getTableRowCount,
  isConnected,
  initBusinessDB,
};
